mapper.update:
UPDATE ultary_story
SET is_deleted = 1,
	deleted_at = NOW()
WHERE story_id = #{storyId}
  AND user_no = #{userNo}
  AND is_deleted = 0

mapper.insert:
INSERT IGNORE INTO ultary_story_view (
	story_id,
	viewer_user_no
) VALUES (
	#{storyId},
	#{viewerUserNo}
)

mapper.select:
SELECT COUNT(1)
FROM ultary_story_view
WHERE story_id = #{storyId}
  AND viewer_user_no = #{viewerUserNo}
